.lsa-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.lsa-root,.lsa-root *,.lsa-root *::before,.lsa-root *::after{box-sizing:border-box}
.lsa-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.lsa-root img{display:block;border:0;max-width:none}
.lsa-root [hidden]{display:none!important}
.lsa-root .nS1_74_447{word-break:break-word;align-content:stretch;display:flex;font-family:"Tomorrow","Pretendard",system-ui,sans-serif;font-weight:400;gap:1px;align-items:center;line-height:normal;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-point, #57beff);white-space:nowrap}
.lsa-root .nS1_74_448{position:relative;flex-shrink:0;font-size:16px;width:21px;line-height:19px;white-space:nowrap}
.lsa-root .nS1_74_449{position:relative;flex-shrink:0;font-size:16px;width:7px;line-height:19px;white-space:nowrap}
.lsa-root [data-name="Widget/Sensor Status"] > * > *{margin-left:0;margin-top:0}
.lsa-root [data-node-id$=";13:354"]{border-image:linear-gradient(to bottom,var(--wa-line, #fff) 60%,var(--wa-point, #7cccff) 60%) 1}
.lsa-root [data-node-id="65:2105"]{border-color:transparent!important;outline:10px solid var(--wa-line, #121829);outline-offset:-5px}
.lsa-root [data-node-id="65:2167"]{border-color:transparent!important;outline:1px solid var(--wa-point, #2861ff);outline-offset:-0.5px}
.lsa-root[data-theme="light"] [data-node-id="65:2167"]{outline-color:var(--wa-point, #517aec)}
.lsa-root [data-node-id="65:2168"]{border-color:transparent!important;outline:1px solid var(--wa-point, #2861ff);outline-offset:-0.5px}
.lsa-root[data-theme="light"] [data-node-id="65:2168"]{outline-color:var(--wa-point, #517aec)}
.lsa-root [data-node-id="65:2173"]{border-color:transparent!important;outline:1px solid var(--wa-point, #2861ff);outline-offset:-0.5px}
.lsa-root[data-theme="light"] [data-node-id="65:2173"]{outline-color:var(--wa-point, #517aec)}
.lsa-root [data-node-id="65:2185"]{border-color:transparent!important;outline:1px solid var(--wa-point, #2861ff);outline-offset:-0.5px}
.lsa-root[data-theme="light"] [data-node-id="65:2185"]{outline-color:var(--wa-point, #517aec)}
.lsa-root [data-node-id="65:2189"]{border-color:transparent!important;outline:1px solid var(--wa-point, #2861ff);outline-offset:-0.5px}
.lsa-root[data-theme="light"] [data-node-id="65:2189"]{outline-color:var(--wa-point, #517aec)}
.lsa-root [data-node-id="65:2193"]{border-color:transparent!important;outline:1px solid var(--wa-point, #2861ff);outline-offset:-0.5px}
.lsa-root[data-theme="light"] [data-node-id="65:2193"]{outline-color:var(--wa-point, #517aec)}
.lsa-root [data-node-id="70:2674"]{border-color:transparent!important;outline:1px solid var(--wa-point, #273458);outline-offset:-0.5px}
.lsa-root{position:absolute;inset:0;background:transparent;z-index:auto;overflow:visible}
.lsa-root[data-theme="light"]{background:var(--wa-bg, #eef2f7);color:var(--wa-text, #0e1a2b)}
.lsa-root[data-theme="light"] [data-name="Background"] > img{filter:invert(1) hue-rotate(180deg) saturate(0.4) brightness(1.05);opacity:0.5}
.lsa-root[data-theme="light"] [data-name="Building Image"] img{filter:saturate(0.92) brightness(0.98)}
.lsa-root[data-theme="light"] [data-name="Floor Plan"] img{filter:invert(1) hue-rotate(180deg) saturate(0.55) brightness(1.04)}
.lsa-root[data-theme="light"] [data-name^="Popup/"] > [data-name="Background"]::after{content:"";position:absolute;inset:0;border-radius:inherit;background:color-mix(in srgb, var(--wa-bg, rgb(247 250 254)) 92%, transparent);pointer-events:none}
.lsa-root[data-theme="light"] .nS1_74_447{color:var(--wa-point, #0469a9)}
